"""Collection and Comparison for resolved, valid Define Particle Operations."""

from __future__ import annotations

import dataclasses
from typing import final

from operation_graph_optimization import graph

# These bound optional work without skipping useful shortcuts on longer
# references. Measurement and crossover trade-offs are in thresholds.md.
MAX_PRUNING_CANDIDATES = 16
MAX_SUPPLIER_SEARCH_CANDIDATES = 16
# Shared traversal avoids repeated searches in wide collections, but starts
# too much traversal work when used for small collections.
MAX_PAIRWISE_COMPARISON_CANDIDATES = 64


@dataclasses.dataclass(slots=True, frozen=True)
class Operation:
    """Requirements of one operation, with repeated position accesses combined."""

    occupied: tuple[int, ...] = ()
    fill: int | None = None
    empty: int | None = None
    creators: tuple[int, ...] = ()
    defines: tuple[int, ...] = ()


@dataclasses.dataclass(slots=True)
class _Position:
    supplier: int
    uses: set[int] | None = None
    creator: int | None = None
    recent_use: int | None = None


def compare(calculated: graph.Graph, candidates: set[int]) -> list[int]:
    """Apply Comparison before adding the current operation's edges."""
    if len(candidates) < 2:
        return list(candidates)
    if len(candidates) == 2:
        first, second = candidates
        if calculated.heights[first] < calculated.heights[second]:
            first, second = second, first
        if calculated.reaches(first, second):
            return [first]
        return [first, second]
    if len(candidates) > MAX_PAIRWISE_COMPARISON_CANDIDATES:
        heights = [calculated.heights[candidate] for candidate in candidates]
        minimum_height = min(heights)
        if minimum_height == max(heights):
            return list(candidates)
        direct: set[int] = set()
        for candidate in candidates:
            for offset in range(
                calculated.offsets[candidate], calculated.offsets[candidate + 1]
            ):
                dependency = calculated.edges[offset]
                if dependency in candidates:
                    direct.add(dependency)
        if direct:
            candidates = candidates - direct
            if len(candidates) < 2:
                return list(candidates)
            minimum_height = min(
                calculated.heights[candidate] for candidate in candidates
            )
        minimum_occurrence = min(candidates)
        expanded = set(candidates)
        excluded: set[int] = set()
        pending = list(candidates)
        while pending:
            current = pending.pop()
            if (
                current <= minimum_occurrence
                or calculated.heights[current] <= minimum_height
            ):
                continue
            for offset in range(
                calculated.offsets[current], calculated.offsets[current + 1]
            ):
                dependency = calculated.edges[offset]
                if dependency in candidates:
                    excluded.add(dependency)
                    if len(excluded) == len(candidates) - 1:
                        return list(candidates - excluded)
                if (
                    calculated.heights[dependency] >= minimum_height
                    and dependency >= minimum_occurrence
                    and dependency not in expanded
                ):
                    expanded.add(dependency)
                    pending.append(dependency)
        return list(candidates - excluded)
    ordered = sorted(candidates, key=calculated.heights.__getitem__, reverse=True)
    if calculated.heights[ordered[0]] == calculated.heights[ordered[-1]]:
        return ordered
    kept: list[int] = []
    for candidate in ordered:
        if not any(calculated.reaches(later, candidate) for later in kept):
            kept.append(candidate)
    return kept


@final
class Calculator:
    """Calculate dependencies while following the specified serial state."""

    def __init__(self, cache_targets: int = 1024, cache_bytes: int = 64 * 1024**2):
        """Keep occupancy analysis separate from dependency reachability."""
        self.graph = graph.Graph(cache_targets, cache_bytes)
        self._positions: dict[int, _Position] = {}

    def retain(self, positions: dict[int, int]):
        """Preserve selected records for shared destructor use before vacancy."""
        for ordinary, retained in positions.items():
            state = self._positions[ordinary]
            uses = None if state.uses is None else state.uses.copy()
            self._positions[retained] = _Position(
                state.supplier,
                uses,
                state.creator,
                state.recent_use,
            )

    def forget(self, positions: tuple[int, ...]):
        """Release records after source analysis proves they have no future uses."""
        for position in positions:
            del self._positions[position]

    def _collect(self, operation: Operation) -> set[int]:
        candidates = set(operation.creators)
        covered_creators: set[int] = set()
        supplied_by_uses: list[_Position] = []
        required = operation.occupied
        if operation.fill is not None:
            required = (*required, operation.fill)
        for position in required:
            state = self._positions.get(position)
            if state is not None:
                candidates.add(state.supplier)
                if state.uses is not None:
                    supplied_by_uses.append(state)
                if state.creator is not None and state.supplier != state.creator:
                    covered_creators.add(state.creator)
        if operation.empty is not None:
            state = self._positions[operation.empty]
            if state.uses is None:
                candidates.add(state.supplier)
            else:
                candidates.update(state.uses)
            if state.creator is not None and (
                state.uses is not None or state.supplier != state.creator
            ):
                covered_creators.add(state.creator)
        candidates.difference_update(covered_creators)
        covered: list[int] = []
        for state in supplied_by_uses:
            if state.supplier not in candidates:
                continue
            assert state.uses is not None  # noqa: S101 - Established when collected above.
            if len(candidates) <= MAX_SUPPLIER_SEARCH_CANDIDATES:
                follows_fill = not candidates.isdisjoint(state.uses)
            else:
                follows_fill = state.recent_use in candidates
            if follows_fill:
                covered.append(state.supplier)
        candidates.difference_update(covered)
        return candidates

    def _record(self, operation: Operation, occurrence: int, dependencies: set[int]):
        for position in operation.occupied:
            state = self._positions[position]
            if state.uses is None:
                state.uses = {occurrence}
            else:
                # Bounding this optional pruning keeps long references from
                # multiplying work by an arbitrarily large dependency count.
                if len(dependencies) <= MAX_PRUNING_CANDIDATES:
                    state.uses.difference_update(dependencies)
                state.uses.add(occurrence)
            state.recent_use = occurrence
        for position in (operation.fill, operation.empty):
            if position is None:
                continue
            state = self._positions.get(position)
            if state is None:
                self._positions[position] = _Position(occurrence)
            else:
                state.supplier = occurrence
                state.uses = None
                state.recent_use = None
        for position in operation.defines:
            self._positions[position] = _Position(occurrence, creator=occurrence)

    def add(self, operation: Operation) -> int:
        """Calculate and record one Create, Move, or Destroy."""
        candidates = self._collect(operation)
        dependencies = compare(self.graph, candidates)
        occurrence = self.graph.append(dependencies)
        self._record(operation, occurrence, candidates)
        return occurrence

    def simultaneous(self, operations: list[Operation]) -> list[int]:
        """Calculate vacancies belonging to one simultaneous destruction."""
        return [self.add(operation) for operation in operations]

sources.graph:
"""Compact append-only dependency storage and bounded reachability indexing."""

from __future__ import annotations

import array
import collections
from typing import final


@final
class Graph:
    """Store calculated dependencies without retaining transitive closure."""

    def __init__(self, cache_targets: int = 1024, cache_bytes: int = 64 * 1024**2):
        """Bound memoized expensive reachability questions independently of width."""
        self.offsets = array.array("Q", [0])
        self.edges = array.array("Q")
        self.heights = array.array("Q")
        self._first_consumer = array.array("q")
        self._next_consumer = array.array("q")
        self._consumers = array.array("Q")
        self._cache_targets = cache_targets
        self._cache_bytes = cache_bytes
        self._columns: collections.OrderedDict[int, bytearray] = (
            collections.OrderedDict()
        )
        self._column_bytes = 0
        self._expensive: collections.OrderedDict[int, int] = collections.OrderedDict()

    def __len__(self) -> int:
        """Count calculated operations."""
        return len(self.heights)

    def dependencies(self, operation: int) -> array.array[int]:
        """Read one operation's direct dependencies."""
        return self.edges[self.offsets[operation] : self.offsets[operation + 1]]

    def append(self, dependencies: list[int]) -> int:
        """Append an operation whose dependencies have already been calculated."""
        operation = len(self)
        height = 0
        for dependency in dependencies:
            dependency_height = self.heights[dependency] + 1
            if dependency_height > height:  # noqa: PLR1730 - Avoid a call per edge.
                height = dependency_height
            self._next_consumer.append(self._first_consumer[dependency])
            self._first_consumer[dependency] = len(self.edges)
            self._consumers.append(operation)
            self.edges.append(dependency)
        self.offsets.append(len(self.edges))
        self.heights.append(height)
        self._first_consumer.append(-1)
        return operation

    def _column(self, previous: int, following: int) -> bytearray:
        column = self._columns.pop(previous, bytearray())
        self._column_bytes -= len(column)
        required = max(len(column), following - previous + 1)
        while self._columns and (
            self._column_bytes + required > self._cache_bytes
            or len(self._columns) >= self._cache_targets
        ):
            _, removed = self._columns.popitem(last=False)
            self._column_bytes -= len(removed)
        column.extend(bytes(required - len(column)))
        column[0] = 2
        self._columns[previous] = column
        self._column_bytes += len(column)
        return column

    def _memoized_reaches(
        self, following: int, previous: int, column: bytearray
    ) -> bool:
        pending = [(following, self.offsets[following])]
        minimum_height = self.heights[previous]
        while pending:
            current, offset = pending[-1]
            if column[current - previous]:
                _ = pending.pop()
            elif offset == self.offsets[current + 1]:
                column[current - previous] = 1
            else:
                dependency = self.edges[offset]
                if dependency < previous:
                    pending[-1] = (current, offset + 1)
                elif column[dependency - previous] == 2:
                    column[current - previous] = 2
                elif (
                    column[dependency - previous] == 0
                    and self.heights[dependency] > minimum_height
                ):
                    pending.append((dependency, self.offsets[dependency]))
                else:
                    pending[-1] = (current, offset + 1)
        return column[following - previous] == 2

    def _repeated_expensive(self, previous: int) -> bool:
        count = self._expensive.pop(previous, 0) + 1
        if count >= 3:
            return True
        self._expensive[previous] = count
        if len(self._expensive) > 1024:
            _ = self._expensive.popitem(last=False)
        return False

    def reaches(self, following: int, previous: int) -> bool:
        """Test strict dependency reachability in the calculated graph."""
        if following <= previous or self.heights[following] <= self.heights[previous]:
            return False
        if self._first_consumer[previous] < 0:
            return False
        if previous in self._columns and following - previous < self._cache_bytes:
            return self._memoized_reaches(
                following, previous, self._column(previous, following)
            )
        backward = collections.deque([(following, self.offsets[following])])
        forward = collections.deque([(previous, self._first_consumer[previous])])
        earlier_seen = {following}
        later_seen = {previous}
        minimum_height = self.heights[previous]
        maximum_height = self.heights[following]
        consider_cache = (
            self._cache_targets > 0 and following - previous < self._cache_bytes
        )
        shared: int | None = None
        while backward and forward:
            if consider_cache and len(earlier_seen) + len(later_seen) >= 64:
                if (
                    shared is not None
                    and self._repeated_expensive(shared)
                    and self._memoized_reaches(
                        following, shared, self._column(shared, following)
                    )
                ):
                    return True
                if self._repeated_expensive(previous):
                    return self._memoized_reaches(
                        following, previous, self._column(previous, following)
                    )
                consider_cache = False
            current, offset = backward[0]
            if offset == self.offsets[current + 1]:
                _ = backward.popleft()
            else:
                dependency = self.edges[offset]
                backward[0] = (current, offset + 1)
                if dependency in later_seen:
                    return True
                if (
                    self.heights[dependency] > minimum_height
                    and dependency > previous
                    and dependency not in earlier_seen
                ):
                    earlier_seen.add(dependency)
                    backward.append((dependency, self.offsets[dependency]))
            current, offset = forward[0]
            if offset < 0:
                _ = forward.popleft()
            else:
                consumer = self._consumers[offset]
                forward[0] = (current, self._next_consumer[offset])
                if consumer in earlier_seen:
                    return True
                if (
                    self.heights[consumer] < maximum_height
                    and consumer < following
                    and consumer not in later_seen
                ):
                    later_seen.add(consumer)
                    if (
                        consumer in self._columns
                        and following - consumer < self._cache_bytes
                    ):
                        if self._memoized_reaches(
                            following, consumer, self._column(consumer, following)
                        ):
                            return True
                    else:
                        if (
                            consider_cache
                            and shared is None
                            and self.offsets[consumer + 1] - self.offsets[consumer] > 1
                        ):
                            shared = consumer
                        forward.append((consumer, self._first_consumer[consumer]))
        return False

sources.vanish:
"""Vanish dependency construction from resolved particle requirements."""

from __future__ import annotations

from typing import override

from operation_graph_optimization import algorithm, graph


class Collector:
    """Retain lifetime candidates until all position dependencies are known."""

    def __init__(self, calculated: graph.Graph):
        """Share the graph whose occurrence identities appear in requirements."""
        self.graph: graph.Graph = calculated
        self.candidates: dict[int, set[int]] = {}
        self.vacates: dict[int, int] = {}

    def _use(self, particle: int, occurrence: int, dependencies: list[int]):
        del dependencies
        self.candidates.setdefault(particle, set()).add(occurrence)

    def observe(self, occurrence: int, particles: tuple[int, ...], vacated: int | None):
        """Include actual quality uses, direct movement, and selected Vacation."""
        dependencies = list(self.graph.dependencies(occurrence))
        for particle in particles:
            if particle != vacated:
                self._use(particle, occurrence, dependencies)
        if vacated is not None:
            self.vacates[vacated] = occurrence
            self._use(vacated, occurrence, dependencies)

    def finish(self) -> dict[int, int]:
        """Append Vanishes without changing position setters or readers."""
        result: dict[int, int] = {}
        for particle in self.vacates:
            candidates = self.candidates.pop(particle)
            result[particle] = self.graph.append(
                algorithm.compare(self.graph, candidates)
            )
        return result


class DirectPruning(Collector):
    """Retire a previous use when the new use directly depends on it."""

    @override
    def _use(self, particle: int, occurrence: int, dependencies: list[int]):
        candidates = self.candidates.setdefault(particle, set())
        candidates.difference_update(dependencies)
        candidates.add(occurrence)


class Incremental(Collector):
    """Maintain the exact antichain after every particle requirement."""

    @override
    def _use(self, particle: int, occurrence: int, dependencies: list[int]):
        del dependencies
        candidates = self.candidates.setdefault(particle, set())
        covered: list[int] = []
        for previous in candidates:
            if self.graph.reaches(occurrence, previous):
                covered.append(previous)
        candidates.difference_update(covered)
        candidates.add(occurrence)

